import {DESTINATIONS,REGION_BY_ID} from './rpg-data.js';
export function drawWorldMap(canvas,{store,current,selected}){const rect=canvas.getBoundingClientRect(),w=Math.max(340,rect.width||640),h=Math.max(380,rect.height||590),ratio=Math.min(globalThis.devicePixelRatio||1,2);canvas.width=w*ratio;canvas.height=h*ratio;const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);const project=r=>({x:(r.x+375)/790*w,y:(r.z+430)/850*h}),hits=[];
 const sea=ctx.createLinearGradient(0,0,w,h);sea.addColorStop(0,'#2d6a7b');sea.addColorStop(1,'#194757');ctx.fillStyle=sea;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#b5e2dd10';ctx.lineWidth=1;for(let x=0;x<w;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
 ctx.font='10px sans-serif';ctx.fillStyle='#c2dace70';ctx.fillText('U-SPEAK ARCHIPELAGO',18,25);ctx.textAlign='right';ctx.fillText('N ↑',w-20,25);
 for(const r of DESTINATIONS){const p=project(r);for(const parent of r.needs||[]){const a=project(REGION_BY_ID[parent]);ctx.beginPath();ctx.setLineDash([4,5]);ctx.lineWidth=store.unlocked(r.id)?1.8:1;ctx.strokeStyle=store.unlocked(r.id)?'#f2dc9f99':'#bbd4d12a';ctx.moveTo(a.x,a.y);ctx.lineTo(p.x,p.y);ctx.stroke()}}ctx.setLineDash([]);
 for(const [index,r]of DESTINATIONS.entries()){const p=project(r),isOpen=store.unlocked(r.id),isSelected=selected===r.id,rx=r.hub?Math.min(w*.07,45):Math.min(w*.093,61),ry=r.hub?Math.min(h*.066,35):Math.min(h*.082,49);hits.push({id:r.id,x:p.x,y:p.y,r:Math.max(rx,ry)+8});const shape=(scale,offset=0)=>{ctx.beginPath();for(let j=0;j<=40;j++){const a=j/40*Math.PI*2,noise=1+.12*Math.sin(a*5+index*2)+.07*Math.cos(a*9+index);const x=p.x+Math.cos(a)*rx*noise*scale,y=p.y+Math.sin(a)*ry*noise*scale+offset;j?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath()};shape(1.08);ctx.fillStyle=isSelected?'#e9d79e':'#a6c8c233';ctx.fill();shape(1);ctx.fillStyle=isOpen?'#d4bd8d':'#66838a';ctx.fill();shape(.88);ctx.fillStyle=isOpen?'#'+r.color.toString(16).padStart(6,'0'):'#526e77';ctx.fill();ctx.strokeStyle=isOpen?'#fff3ca99':'#ccddd555';ctx.lineWidth=isSelected?2:1;ctx.stroke();ctx.save();shape(.83);ctx.clip();for(let j=0;j<6;j++){shape(.7-j*.08,(j-2)*2);ctx.strokeStyle=isOpen?'#29493828':'#bacfcb0c';ctx.lineWidth=1;ctx.stroke()}ctx.restore();
 if(isSelected){ctx.beginPath();ctx.arc(p.x,p.y,18,0,Math.PI*2);ctx.strokeStyle='#fff0b4';ctx.lineWidth=2;ctx.stroke()}
 ctx.beginPath();ctx.arc(p.x,p.y,13,0,Math.PI*2);ctx.fillStyle=r.id===current?'#fff2cc':isOpen?'#244a53':'#45616b';ctx.fill();ctx.strokeStyle=isOpen?'#e5d5ac':'#7e9897';ctx.lineWidth=1.5;ctx.stroke();ctx.font='600 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=r.id===current?'#28565c':isOpen?'#f6e7bc':'#bac9c1';ctx.fillText(r.id===current?'●':r.hub?'✈':isOpen?(store.cleared(r.id)?'✓':String(index-1).padStart(2,'0')):'?',p.x,p.y);
 ctx.font=`600 ${w<450?10:12}px sans-serif`;ctx.lineWidth=4;ctx.strokeStyle='#204451';const title=r.id==='park'?'テーマパーク':r.name;ctx.strokeText(title,p.x,p.y+26);ctx.fillStyle=isOpen?'#fff0cf':'#adc3bd';ctx.fillText(title,p.x,p.y+26);if(!r.hub){ctx.font='9px sans-serif';ctx.fillStyle=isOpen?'#e9e1bf':'#a1bcb7';ctx.fillText(isOpen?`${store.count(r.id)} / 10`:'未解放',p.x,p.y+40)}}
 ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle='#d5dfcbab';ctx.font='10px sans-serif';ctx.fillText('地域を選択して航空路を確認',18,h-17);return {hits,width:w,height:h};}
